(function () {
  const ALPHA = '0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ';
  const TRACKS = {
    stream: [0.000, 30, ''],
    street: [1.750, 12, 'fvfv0fvfv0fvfv0fvfv0fvfv0xefV6qwhdizSkCWoDlXTyuqKXmbpUVwPvbZsjvhZwZFiWrDFaVwWJcffvfv0fvfv0fvfv0fvfv0fvfv0fvfv0xefVEqvhfRzUkWXoNmKZyxr4XmoryYwRvDZsmvKZx3FGQrDFBTwWJc6fvfv0fvfv0fvfv0fvfv0fvfv0fvfv0xcfXJqthlQzXl8XoSnjYyBriXmzsIYwSvWZsnw3Zx4FXPrzFQRwWJc6fvfv0'],
    bend: [2.000, 12, 'r3lQYrxkyYqlkDPtghPVfvfv0x1jDYqhlYZzZpGWpZusYyWvDVpYBDXxqAiYsWARZxFIQwrOIXGfvfv0fvfv0r9lWYrCkIZqtkLJtli1Xfvfv0xcjZYqnmfYA5q9Xq1uIYyVwbWq8C1XxqAPYsUBkZxAJ2irVJ8ofvfv0fvfv0rflRZrIkEZqCkHPtsi1Yfvfv0xmkhZqtmuYAaqAYq1uYXyWwxXq8CkVxpBkYsSBNYxAJ26rVJ86fvfv0fvfv0'],
    crocs: [2.250, 12, ''],
    clips: [2.583, 12, ''],
    horns: [4.750, 12, ''],
    bed: [5.400, 30, ''],
    beach: [16.917, 12, ''],
    juice: [27.167, 12, ''],
    greece: [30.633, 30, ''],
    towel: [38.300, 30, ''],
    studio: [42.167, 12, ''],
    bra: [45.100, 30, ''],
    ginger: [23.500, 12, ''],
    stripe: [23.500, 12, ''],
    specs: [23.500, 12, ''],
    longhair: [23.500, 12, ''],
    zip: [23.500, 12, '']
  };
  const VOICE = '';

  function pair(s, i) {
    return ALPHA.indexOf(s[i]) * 62 + ALPHA.indexOf(s[i + 1]);
  }

  function frameAt(str, i) {
    const out = [];
    for (let k = 0; k < 17; k++) {
      const o = (i * 17 + k) * 5;
      out.push([(pair(str, o) / 3843) * 2 - 0.5, (pair(str, o + 2) / 3843) * 2 - 0.5, ALPHA.indexOf(str[o + 4]) / 61]);
    }
    return out;
  }

  function at(name, t) {
    const tr = TRACKS[name];
    if (!tr) return null;
    const n = tr[2].length / 85;
    const x = Math.max(0, Math.min(n - 1, (t - tr[0]) * tr[1]));
    const i = Math.min(n - 2, Math.floor(x));
    if (n < 2) return frameAt(tr[2], 0);
    const a = frameAt(tr[2], i), b = frameAt(tr[2], i + 1);
    const u = x - i;
    return a.map((p, k) => [p[0] + (b[k][0] - p[0]) * u, p[1] + (b[k][1] - p[1]) * u, Math.min(p[2], b[k][2])]);
  }

  function voice(t) {
    const x = t * 20;
    const i = Math.floor(x);
    if (i < 0 || i >= VOICE.length - 1) return 0;
    const a = ALPHA.indexOf(VOICE[i]) / 61, b = ALPHA.indexOf(VOICE[i + 1]) / 61;
    return a + (b - a) * (x - i);
  }

  window.StsTrack = { names: Object.keys(TRACKS), at, voice };
})();
